-- Fichier généré par scripts/generate-seed.mjs. Ne pas modifier à la main.
-- Contenu initial : 5 audios de centrage, diagnostic, scénarios du Dojo.

insert into public.audio_exercises (title, description, audio_url, category, duration_seconds, is_active, position) values
  ('Scan corporel', 'Parcourir le corps, de la tête aux pieds, pour revenir dans l’instant avant la journée.', 'https://res.cloudinary.com/ncu7idmv/video/upload/v1794424390/PQ_scan_corporel_6min30.m4a', 'centering', 391, true, 1),
  ('Tactile', 'S’ancrer par le toucher : les points de contact, la texture, la température.', 'https://res.cloudinary.com/ncu7idmv/video/upload/v1794424384/PQ_tactile_2min30.m4a', 'centering', 150, true, 2),
  ('Sonore', 'Accueillir les sons autour de vous, sans les juger, pour calmer le mental.', 'https://res.cloudinary.com/ncu7idmv/video/upload/v1794424384/PQ_sonore_2min30.m4a', 'centering', 157, true, 3),
  ('Sensations respiratoires', 'Suivre le souffle tel qu’il est, pour retrouver un rythme plus posé.', 'https://res.cloudinary.com/ncu7idmv/video/upload/v1794424384/PQ_sensations_respi_2min30.m4a', 'centering', 161, true, 4),
  ('Visuel', 'Poser le regard, observer ce qui est là, et laisser l’attention se stabiliser.', 'https://res.cloudinary.com/ncu7idmv/video/upload/v1794424383/PQ_visuel_2min30.m4a', 'centering', 164, true, 5);

with q as (
  insert into public.diagnostic_questions (question, position, is_active) values ('Une conversation délicate se profile : un désaccord, une demande à faire. Le plus souvent, vous…', 1, true) returning id
)
insert into public.diagnostic_answers (question_id, answer_label, reflex_type, score)
select q.id, v.label, v.reflex, 1 from q, (values
  ('La repoussez, en espérant qu’elle ne soit bientôt plus nécessaire.', 'avoidance'),
  ('Pensez surtout à ce que l’autre attend, pour ne pas le contrarier.', 'accommodation'),
  ('Préparez vos arguments pour ne pas vous laisser faire.', 'defense'),
  ('Planifiez précisément le déroulé, pour que rien ne vous échappe.', 'control'),
  ('Sentez déjà une boule au ventre et redoutez de rester sans voix.', 'withdrawal')
) as v(label, reflex);

with q as (
  insert into public.diagnostic_questions (question, position, is_active) values ('On vous adresse une critique que vous trouvez injuste. Votre premier réflexe :', 2, true) returning id
)
insert into public.diagnostic_answers (question_id, answer_label, reflex_type, score)
select q.id, v.label, v.reflex, 1 from q, (values
  ('Me justifier tout de suite, point par point.', 'defense'),
  ('M’excuser, même si je ne suis pas d’accord.', 'accommodation'),
  ('Changer de sujet ou minimiser pour passer à autre chose.', 'avoidance'),
  ('Recadrer la discussion pour reprendre la main.', 'control'),
  ('Me taire et me fermer, quitte à y repenser pendant des heures.', 'withdrawal')
) as v(label, reflex);

with q as (
  insert into public.diagnostic_questions (question, position, is_active) values ('Au milieu d’un échange qui se tend, ce qui vous arrive le plus souvent :', 3, true) returning id
)
insert into public.diagnostic_answers (question_id, answer_label, reflex_type, score)
select q.id, v.label, v.reflex, 1 from q, (values
  ('Je perds mes mots, j’ai la tête vide.', 'withdrawal'),
  ('Le ton monte, je réponds du tac au tac.', 'defense'),
  ('Je coupe la parole pour orienter la conversation.', 'control'),
  ('Je cède pour que la tension retombe.', 'accommodation'),
  ('Je trouve une raison d’écourter la conversation.', 'avoidance')
) as v(label, reflex);

with q as (
  insert into public.diagnostic_questions (question, position, is_active) values ('Après une conversation difficile, vous vous dites souvent :', 4, true) returning id
)
insert into public.diagnostic_answers (question_id, answer_label, reflex_type, score)
select q.id, v.label, v.reflex, 1 from q, (values
  ('« J’aurais dû dire ce dont j’avais vraiment besoin. »', 'accommodation'),
  ('« J’ai réagi trop vite, trop fort. »', 'defense'),
  ('« Je n’ai presque rien dit de ce que je pensais. »', 'withdrawal'),
  ('« Je n’ai pas vraiment écouté ce que l’autre voulait dire. »', 'control'),
  ('« Finalement, on n’a pas parlé du vrai sujet. »', 'avoidance')
) as v(label, reflex);

with q as (
  insert into public.diagnostic_questions (question, position, is_active) values ('Dans une conversation importante, ce qui vous rassure le plus :', 5, true) returning id
)
insert into public.diagnostic_answers (question_id, answer_label, reflex_type, score)
select q.id, v.label, v.reflex, 1 from q, (values
  ('Savoir exactement où l’on va, et comment.', 'control'),
  ('Sentir que l’autre est satisfait.', 'accommodation'),
  ('Que cela ne dure pas trop longtemps.', 'avoidance'),
  ('Avoir de bons arguments en réserve.', 'defense'),
  ('Pouvoir prendre du recul et y revenir plus tard.', 'withdrawal')
) as v(label, reflex);

insert into public.exercises (title, description, category, content, estimated_duration, difficulty_level, is_active) values
  ('Dire non à une demande de dernière minute', 'Refuser sans se justifier pendant dix minutes, et sans fermer la porte.', 'Travail', '{"context":"Il est 17 h 30. Une personne de votre équipe vous demande de reprendre un dossier urgent pour demain matin. Votre soirée est déjà prise.","goal":"Dire non clairement, tout en restant dans la relation.","steps":[{"other_says":"« Tu pourrais regarder ça ce soir ? C’est vraiment urgent, je n’ai personne d’autre. »","prompt":"Que répondez-vous ?","options":[{"label":"« Euh… oui, bon, je vais essayer de trouver du temps. »","tone":"a_explorer","feedback":"Un oui contraint laisse souvent un goût amer et ne règle pas la question. Qu’est-ce qui vous empêcherait de dire non ici ?"},{"label":"« Je comprends que ce soit urgent. Ce soir, je ne suis pas disponible. Je peux y regarder demain à 9 h. »","tone":"ajuste","feedback":"Vous reconnaissez la contrainte de l’autre, posez votre limite et proposez une alternative réaliste. C’est clair et respectueux."},{"label":"« Encore ? C’est toujours à moi qu’on demande ça. »","tone":"a_explorer","feedback":"La frustration est légitime, mais le reproche risque de déplacer la conversation. Votre limite reste à formuler."}]},{"other_says":"« Demain, ce sera trop tard. Tu ne peux vraiment pas faire un effort ? »","prompt":"La pression monte. Que dites-vous ?","options":[{"label":"« Je comprends. Ma réponse reste la même pour ce soir. Veux-tu qu’on voie ensemble qui d’autre pourrait aider ? »","tone":"ajuste","feedback":"Vous tenez votre limite sans la rejustifier, et vous restez coopératif ou coopérative sur le problème."},{"label":"« J’ai un rendez-vous important, et puis j’ai déjà beaucoup travaillé cette semaine, et… »","tone":"a_explorer","feedback":"Multiplier les justifications ouvre la négociation. Une limite n’a pas besoin d’être prouvée pour être valable."},{"label":"« Bon, d’accord. »","tone":"a_explorer","feedback":"Céder à la deuxième relance est très courant. Qu’auriez-vous besoin de vous dire pour tenir votre position ?"}]}],"reflection":["Qu’avez-vous ressenti au moment de dire non ?","Quelle phrase aimeriez-vous garder pour une prochaine fois ?"]}'::jsonb, 4, 'debutant', true),
  ('Recevoir une critique en réunion', 'Accueillir un retour difficile sans se justifier aussitôt.', 'Travail', '{"context":"En réunion, devant l’équipe, quelqu’un remet en cause la qualité de votre présentation.","goal":"Écouter, clarifier, puis répondre avec calme.","steps":[{"other_says":"« Honnêtement, les chiffres présentés ne sont pas fiables. On ne peut pas décider sur cette base. »","prompt":"Votre première réaction ?","options":[{"label":"« Ils sont parfaitement fiables, j’ai passé deux jours dessus. »","tone":"a_explorer","feedback":"La défense immédiate est naturelle, mais elle ferme l’échange avant d’avoir compris l’objection."},{"label":"« Qu’est-ce qui te fait douter précisément ? »","tone":"ajuste","feedback":"Une question de clarification vous donne du temps et ramène la discussion sur des faits."},{"label":"Vous ne dites rien et passez à la diapositive suivante.","tone":"a_explorer","feedback":"Se retirer évite la tension sur le moment, mais la question reste en suspens pour tout le monde."}]},{"other_says":"« Les données de mars ne correspondent pas à ce qu’on a vu en comité. »","prompt":"Vous avez maintenant une objection précise. Que dites-vous ?","options":[{"label":"« C’est possible, je vérifie et je reviens vers vous demain avec la version corrigée si besoin. »","tone":"ajuste","feedback":"Vous reconnaissez le point sans vous dévaloriser, et vous proposez une suite concrète."},{"label":"« Désolé, je suis vraiment nul avec les chiffres. »","tone":"a_explorer","feedback":"Une erreur possible ne dit rien de votre valeur. Séparer le travail de la personne aide à rester stable."},{"label":"« Tout le monde fait des erreurs, ce n’est pas le sujet. »","tone":"a_explorer","feedback":"Minimiser peut donner l’impression de ne pas prendre l’objection au sérieux."}]}],"reflection":["Où avez-vous senti la critique dans votre corps ?","Qu’est-ce qui vous aide à distinguer une critique de votre travail d’une critique de vous ?"]}'::jsonb, 5, 'intermediaire', true),
  ('Poser une limite avec un proche', 'Exprimer une limite à quelqu’un que l’on aime, sans culpabiliser.', 'Famille', '{"context":"Un parent passe régulièrement chez vous sans prévenir. Vous aimeriez être prévenu ou prévenue avant.","goal":"Formuler la limite simplement, en parlant de vous.","steps":[{"other_says":"« Coucou ! J’étais dans le quartier, je suis passé te voir. »","prompt":"Comment abordez-vous le sujet ?","options":[{"label":"« Ça me fait plaisir de te voir. J’aimerais qu’on en parle : je préfère que tu me préviennes avant de passer. »","tone":"ajuste","feedback":"Vous commencez par le lien, puis vous exprimez votre préférence en « je ». C’est direct et chaleureux."},{"label":"« Tu pourrais quand même prévenir, c’est pénible à la fin. »","tone":"a_explorer","feedback":"Le fond est juste, mais la forme en reproche risque de provoquer une défense."},{"label":"Vous souriez, et vous n’en parlez pas, encore une fois.","tone":"a_explorer","feedback":"Se taire préserve le moment, mais la gêne risque de revenir à chaque visite."}]},{"other_says":"« Ah bon ? Je ne savais pas que je dérangeais… »","prompt":"La personne semble blessée. Que répondez-vous ?","options":[{"label":"« Tu ne déranges pas, je tiens à toi. C’est juste que j’ai besoin de savoir à l’avance pour être disponible. »","tone":"ajuste","feedback":"Vous rassurez sur la relation sans retirer votre besoin. Les deux peuvent coexister."},{"label":"« Non, non, laisse tomber, ce n’est rien. »","tone":"a_explorer","feedback":"Retirer la demande face à la peine de l’autre est fréquent. Votre besoin reste pourtant valable."},{"label":"« Si, un peu, honnêtement. »","tone":"a_explorer","feedback":"C’est sincère, mais sans explication cela peut être reçu comme un rejet."}]}],"reflection":["Qu’est-ce qui rend une limite difficile à poser avec cette personne ?","Comment pourriez-vous vous rappeler que poser une limite protège aussi la relation ?"]}'::jsonb, 4, 'debutant', true),
  ('Exprimer un besoin dans le couple', 'Parler de ce qui vous manque sans que cela devienne un reproche.', 'Couple', '{"context":"Depuis quelques semaines, vous avez le sentiment de passer peu de temps de qualité ensemble.","goal":"Exprimer un besoin et ouvrir la discussion.","steps":[{"other_says":"« Quelque chose te préoccupe en ce moment ? »","prompt":"C’est l’occasion. Que dites-vous ?","options":[{"label":"« Tu n’es jamais là pour moi, tu passes ta vie sur ton téléphone. »","tone":"a_explorer","feedback":"Les mots « jamais » et « toujours » sont souvent reçus comme des attaques. Le besoin derrière reste à dire."},{"label":"« Oui. Ces dernières semaines, j’ai l’impression qu’on se voit peu vraiment. Ça me manque. »","tone":"ajuste","feedback":"Vous décrivez une situation, ce que vous ressentez, et vous restez dans le « je ». C’est une ouverture."},{"label":"« Non, rien, c’est juste la fatigue. »","tone":"a_explorer","feedback":"L’autre vous tend une perche. Qu’est-ce qui rend difficile de la saisir ?"}]},{"other_says":"« Je suis débordé en ce moment, tu le sais bien. »","prompt":"L’autre se justifie. Comment poursuivez-vous ?","options":[{"label":"« Je sais. Je ne te reproche rien. Est-ce qu’on pourrait garder une soirée par semaine rien que pour nous ? »","tone":"ajuste","feedback":"Vous reconnaissez sa réalité, vous retirez la charge de reproche et vous faites une demande concrète."},{"label":"« Tu es toujours débordé, c’est une excuse. »","tone":"a_explorer","feedback":"La conversation risque de devenir un débat sur qui a raison, plutôt que sur ce dont vous avez besoin."},{"label":"« Bon, tant pis, on verra plus tard. »","tone":"a_explorer","feedback":"Repousser est tentant, mais votre besoin n’a pas encore été entendu."}]}],"reflection":["Quel est le besoin le plus important pour vous dans cette situation ?","Quelle demande concrète pourriez-vous faire cette semaine ?"]}'::jsonb, 5, 'intermediaire', true),
  ('Revenir sur une dispute avec un ami', 'Reprendre une conversation qui s’est mal terminée.', 'Amitié', '{"context":"La semaine dernière, une discussion avec un ami proche a dégénéré. Depuis, vous ne vous êtes pas reparlé.","goal":"Rouvrir le dialogue, reconnaître sa part, écouter l’autre.","steps":[{"other_says":"« Salut. Tu voulais qu’on se parle ? »","prompt":"Comment ouvrez-vous ?","options":[{"label":"« Oui. Notre dernière discussion me reste en tête. J’aimerais comprendre comment tu l’as vécue, et te dire comment moi je l’ai vécue. »","tone":"ajuste","feedback":"Vous posez le cadre d’un échange dans les deux sens, sans désigner de coupable."},{"label":"« Je voulais que tu t’excuses pour ce que tu as dit. »","tone":"a_explorer","feedback":"Commencer par une exigence met l’autre en position de défense dès la première phrase."},{"label":"« Oublions, ce n’était pas grave. »","tone":"a_explorer","feedback":"Si ce n’était pas grave, vous ne seriez peut-être pas là. Qu’est-ce qui mérite d’être dit ?"}]},{"other_says":"« Franchement, j’ai trouvé que tu m’avais parlé de haut. »","prompt":"Ce n’est pas comme ça que vous l’avez vécu. Que dites-vous ?","options":[{"label":"« Ce n’était pas mon intention, mais j’entends que tu l’as reçu comme ça. Qu’est-ce qui t’a fait cet effet ? »","tone":"ajuste","feedback":"Vous distinguez votre intention de l’effet produit, et vous continuez à écouter. C’est souvent ce qui débloque."},{"label":"« Pas du tout, c’est toi qui t’es emporté. »","tone":"a_explorer","feedback":"Corriger la perception de l’autre relance souvent la dispute initiale."},{"label":"« D’accord, c’est entièrement ma faute. »","tone":"a_explorer","feedback":"Prendre toute la responsabilité apaise un temps, mais votre version reste non dite."}]}],"reflection":["Qu’avez-vous appris sur la façon dont l’autre a vécu la situation ?","Quelle part de responsabilité êtes-vous prêt ou prête à reconnaître ?"]}'::jsonb, 6, 'avance', true),
  ('Demander une augmentation', 'Formuler une demande importante et tenir face à un premier refus.', 'Travail', '{"context":"Vous avez obtenu un rendez-vous avec votre responsable pour parler de votre rémunération.","goal":"Faire une demande claire, l’étayer, et rester stable face à l’objection.","steps":[{"other_says":"« Je t’écoute, de quoi voulais-tu parler ? »","prompt":"Comment formulez-vous votre demande ?","options":[{"label":"« Je sais que ce n’est sûrement pas le moment, mais si jamais c’était possible… »","tone":"a_explorer","feedback":"Les précautions affaiblissent la demande avant même qu’elle soit posée."},{"label":"« Je souhaite parler de ma rémunération. Sur l’année, j’ai pris en charge X et Y. Je demande une augmentation de Z. »","tone":"ajuste","feedback":"Demande explicite, faits concrets, chiffre précis : votre interlocuteur sait exactement de quoi on parle."},{"label":"« Si je n’ai pas d’augmentation, je vais devoir regarder ailleurs. »","tone":"a_explorer","feedback":"Un ultimatum en ouverture installe un rapport de force difficile à défaire."}]},{"other_says":"« Le budget est serré cette année, je ne peux rien promettre. »","prompt":"Premier refus. Que répondez-vous ?","options":[{"label":"« D’accord, tant pis. »","tone":"a_explorer","feedback":"Renoncer au premier obstacle est fréquent. Il existe souvent un espace de discussion."},{"label":"« J’entends la contrainte. Qu’est-ce qui serait possible, et à quelle échéance pourrait-on en reparler ? »","tone":"ajuste","feedback":"Vous respectez la contrainte, tout en gardant la conversation ouverte et en cherchant une suite datée."},{"label":"« Le budget est toujours serré quand il s’agit de moi. »","tone":"a_explorer","feedback":"Le sentiment d’injustice est compréhensible, mais il risque de faire dévier l’échange."}]}],"reflection":["Qu’est-ce qui vous a semblé le plus difficile à dire ?","De quels faits concrets aimeriez-vous disposer pour une vraie demande ?"]}'::jsonb, 6, 'avance', true);
